WITH store_ret_agg AS ( SELECT cd.cd_education_status AS education_status, cd.cd_marital_status AS marital_status, SUM(sr.sr_net_loss) AS store_net_loss, COUNT(*) AS store_return_cnt FROM store_returns sr JOIN customer_demographics cd ON sr.sr_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk WHERE cd.cd_purchase_estimate > 1500 AND cd.cd_education_status IN ('College', '4 yr Degree') AND hd.hd_vehicle_count > 1 GROUP BY cd.cd_education_status, cd.cd_marital_status ), web_ret_agg AS ( SELECT cd.cd_education_status AS education_status, cd.cd_marital_status AS marital_status, SUM(wr.wr_net_loss) AS web_net_loss, COUNT(*) AS web_return_cnt FROM web_returns wr JOIN customer_demographics cd ON wr.wr_refunded_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON wr.wr_refunded_hdemo_sk = hd.hd_demo_sk WHERE cd.cd_purchase_estimate > 1500 AND cd.cd_education_status IN ('College', '4 yr Degree') AND hd.hd_vehicle_count > 1 GROUP BY cd.cd_education_status, cd.cd_marital_status ) SELECT COALESCE(s.education_status, w.education_status) AS education_status, COALESCE(s.marital_status, w.marital_status) AS marital_status, COALESCE(s.store_net_loss, 0) + COALESCE(w.web_net_loss, 0) AS total_net_loss, COALESCE(s.store_return_cnt, 0) AS store_return_cnt, COALESCE(w.web_return_cnt, 0) AS web_return_cnt, RANK() OVER (ORDER BY (COALESCE(s.store_net_loss, 0) + COALESCE(w.web_net_loss, 0)) DESC) AS loss_rank FROM store_ret_agg s FULL OUTER JOIN web_ret_agg w ON s.education_status = w.education_status AND s.marital_status = w.marital_status ORDER BY total_net_loss DESC LIMIT 20
